#[test]
fn provider_output_redacts_mcp_and_bearer_secrets() {
    let token = "super-secret-token";
    assert_eq!(
        redact_sensitive_provider_output(
            "Authorization: Bearer super-secret-token",
            token,
        ),
        "Authorization: Bearer [REDACTED]"
    );
    assert_eq!(
        redact_sensitive_provider_output(
            "GAMEENGINE_MCP_AUTH_TOKEN=super-secret-token",
            token,
        ),
        "GAMEENGINE_MCP_AUTH_TOKEN=[REDACTED]"
    );
}

#[test]
fn provider_semantic_progress_is_structured_json() {
    let event: ProviderAgentEvent = serde_json::from_str(
        r#"{"type":"progress","step":"inspect","detail":"scene"}"#,
    )
    .expect("semantic event");
    assert!(matches!(
        event,
        ProviderAgentEvent::Progress { step, detail }
            if step == "inspect" && detail == "scene"
    ));
}

